#!/usr/bin/env node
// The wasm golden check (specs/08 section 10.1, issue #122): loads the C# engine in headless Chromium, calls
// Engine.GoldenVectors() (the battle, training-run, gauntlet and tower vectors of the bot CLI's `golden` verb, generated by the
// browser build) and compares each file's text with golden/. A difference means the WebAssembly build resolves fights or runs
// differently from .NET (or the dist is stale: rerun web/wasm/build.sh). Exit 1 on any difference or error.
// Usage: node web/wasm/test/golden.js
'use strict';
const fs = require('fs');
const path = require('path');
const { chromium } = require('playwright');
const { start } = require('./serve.js');

const WEB = path.resolve(__dirname, '..', '..');
const GOLDEN = path.resolve(WEB, '..', 'golden');

// Null when equal; else the first differing lines, like GoldenFiles.Compare on the .NET side.
function compare(name, expected, actual) {
  if (expected === actual) return null;
  const exp = expected.split('\n'), act = actual.split('\n');
  const out = [name + ': MISMATCH between the WebAssembly build and golden/'];
  for (let i = 0, shown = 0; i < Math.max(exp.length, act.length) && shown < 20; i++) {
    if (exp[i] === act[i]) continue;
    if (exp[i] !== undefined) out.push('  -' + exp[i]);
    if (act[i] !== undefined) out.push('  +' + act[i]);
    shown++;
  }
  return out.join('\n');
}

(async () => {
  if (!fs.existsSync(path.join(WEB, 'wasm', 'dist', '_framework', 'dotnet.js'))) { console.error('web/wasm/dist is missing: run web/wasm/build.sh first'); process.exit(2); }
  const srv = await start(WEB, 0);
  const browser = await chromium.launch();
  let bad = 0;
  try {
    const page = await browser.newPage();
    const errors = [];
    page.on('pageerror', (e) => errors.push('pageerror: ' + e.message));
    // A bare page at the web root, so web/engine.js finds wasm/dist/ as the trainer page does; nothing of the UI loads.
    await page.route(srv.url + 'golden-check.html', (r) => r.fulfill({ contentType: 'text/html', body: '<!doctype html><script src="engine.js"></script>' }));
    await page.goto(srv.url + 'golden-check.html');
    const t0 = Date.now();
    const res = await page.evaluate(async () => {
      const { host, contentPack } = await IdleEngine.loadWasm({ timeoutMs: 90000 });
      host.RunInit(contentPack);
      return host.GoldenVectors();
    });
    const ms = Date.now() - t0;
    const got = JSON.parse(res);
    if (got.error) throw new Error('GoldenVectors: ' + got.error);
    const want = fs.readdirSync(GOLDEN).filter((f) => f.endsWith('.txt')).sort();
    const names = got.files.map((f) => f.name).sort();
    if (JSON.stringify(want) !== JSON.stringify(names)) { console.log('FAIL golden/ holds ' + want.join(', ') + ' but the browser build generated ' + names.join(', ')); bad++; }
    for (const f of got.files) {
      const p = path.join(GOLDEN, f.name);
      if (!fs.existsSync(p)) continue;   // reported above
      const diff = compare(f.name, fs.readFileSync(p, 'utf8').replace(/\r\n/g, '\n'), f.text);
      if (diff) { console.log('FAIL ' + diff); bad++; } else console.log('OK   ' + f.name + ' (wasm)');
    }
    for (const e of errors) { console.log('FAIL ' + e); bad++; }
    console.log('wasm golden vectors in ' + (ms / 1000).toFixed(1) + ' s');
  } finally {
    await browser.close();
    await srv.close();
  }
  if (bad) { console.log('\n' + bad + ' FAILED (if golden/ itself is current, the WebAssembly build drifted from .NET: specs/08 section 10.1)'); process.exit(1); }
  console.log('\nall passed');
})().catch((e) => { console.error(e); process.exit(1); });
